From 735be7d7289fb5660ace1e5627247fc8c088dd4e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:07:18 +0100
Subject: [PATCH] containments/desktop: keep dropped icons inside the grid

Dropping an icon past the top or left edge of the desktop gave a
negative cell, which wrapped around to the end of the previous column or
row, so the icon jumped to the far side. Clamp the target into the grid.

BUG: 479085
---
 .../desktop/package/contents/ui/FolderView.qml | 18 +++++-------------
 1 file changed, 5 insertions(+), 13 deletions(-)

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
index b858d16f7a..dc1011e360 100644
--- a/containments/desktop/package/contents/ui/FolderView.qml
+++ b/containments/desktop/package/contents/ui/FolderView.qml
@@ -1302,20 +1302,12 @@ FocusScope {
                     row = rows ? Math.floor(itemY / gridView.cellHeight) : Math.floor(itemX / gridView.cellWidth);


-                    if (col <= positioner.perStripe) {
-                        // We have somehow moved the item outside of the available
-                        // areas (usually during file creation), so make sure
-                        // the col is within perStripe
-                        if (col === positioner.perStripe) {
-                            col -= 1;
-                        }
-
-                        to = (row * positioner.perStripe) + col;
+                    // The item may have been dropped outside of the grid (e.g. past
+                    // the screen edge), so move it to the nearest cell inside it
+                    col = Math.max(0, Math.min(col, positioner.perStripe - 1));
+                    row = Math.max(0, row);

-                        if (to < 0) {
-                            return;
-                        }
-                    }
+                    to = (row * positioner.perStripe) + col;

                     if (from !== to) {
                         moves.push(from);
